from src.nodes.base import BaseNode
from src.runtime.environment.environment_zone_builder import get_environment_zone_builder
from src.runtime.environment.environment_blueprint import EnvironmentBlueprint
import json

class Hou_Mcp_Environment_Zones(BaseNode):
    name = "hou_mcp_environment_zones"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("environment_name", "string", widget_type="text", default="western_room")
        self.add_input("blueprint_json",   "string", widget_type="text", default="")
        self.add_output("zones_json",             "string")
        self.add_output("zone_count",             "int")
        self.add_output("validation_errors_json", "string")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        env_name = (inputs.get("environment_name") or "").strip()
        bp_json  = (inputs.get("blueprint_json") or "").strip()

        if not env_name:
            self.log_error("No environment_name provided.")
            return {"zones_json": "{}", "zone_count": 0, "validation_errors_json": "[]", "exec_out": True}

        try:
            builder = get_environment_zone_builder()
            blueprint = None
            if bp_json:
                try:
                    blueprint = EnvironmentBlueprint.from_dict(json.loads(bp_json))
                except Exception:
                    pass

            zone_plan = builder.build_zones(env_name, blueprint)
            errors = builder.validate_zones(zone_plan)

            if errors:
                self.log_error(f"Zone validation errors: {errors}")
            else:
                self.log_info(f"Zones for '{env_name}': {zone_plan.zone_count} zones")

            return {
                "zones_json":             json.dumps(zone_plan.to_dict(), sort_keys=True, default=str),
                "zone_count":             zone_plan.zone_count,
                "validation_errors_json": json.dumps(errors, default=str),
                "exec_out": True,
            }
        except Exception as exc:
            self.log_error(f"Zone build failed: {exc}")
            return {"zones_json": "{}", "zone_count": 0, "validation_errors_json": "[]", "exec_out": True}

def register_node():
    return Hou_Mcp_Environment_Zones
